$offered=domain_tlds();$mainProduct=$domain?domain_product_for($domain):null;$alternatives=$domain?domain_suggestions($domain,$offset):[];
?>
<section class="container compact-page domain-shop"><div class="page-heading"><div class="eyebrow">DEINE ADRESSE IM INTERNET</div><h1>Ist deine Wunschdomain noch frei?</h1><p>Finde deine Domain und passende Alternativen zu unseren Preisen.</p></div><form class="domain-form domain-search-wide" action="/domain-pruefen" data-domain-search data-reward-id="<?= (int)($_GET['reward_id']??0) ?>"><?php if((int)($_GET['reward_id']??0)): ?><input type="hidden" name="reward_id" value="<?= (int)$_GET['reward_id'] ?>"><?php endif ?><input type="hidden" name="pruefen" value="1"><label class="sr-only" for="lookup-domain">Wunschdomain</label><input id="lookup-domain" name="domain" value="<?= e($raw) ?>" placeholder="deine-idee.de" maxlength="253" required><button class="button button-teal">Domain prüfen <?= icon('search') ?></button></form>
<?php if($lookupError): ?><div class="notice notice-error" role="alert"><?= icon('globe') ?><span><?= e($lookupError) ?></span></div><?php endif ?>
<?php if($domain): ?>
<article class="panel domain-result domain-result-main" data-domain-row data-domain="<?= e($domain) ?>" data-domain-checked="<?= $initial?'1':'0' ?>"><span class="round-icon"><?= icon('globe') ?></span><div class="domain-result-copy"><div class="eyebrow" data-domain-status><?= $initial?e(['available'=>'AKTUELL REGISTRIERBAR','unavailable'=>'NICHT NEU REGISTRIERBAR','unsupported'=>'NICHT IM SORTIMENT'][$initial['status']]??'PRÜFUNG ERFORDERLICH'):'VERFÜGBARKEIT PRÜFEN' ?></div><h2><?= e($domain) ?></h2><p data-domain-message><?= e($initial['message']??'Wir prüfen diese Domain direkt bei OVHcloud.') ?></p></div><div class="domain-result-offer"><strong data-domain-price><?= e($initial['price']??domain_price_label($mainProduct)) ?></strong><small data-domain-tax-note><?= e($initial['tax_note']??'inkl. 19 % MwSt. / Registrierungsjahr') ?></small><a data-domain-action class="button button-teal button-small" href="<?= e(($initial['url']??domain_search_url($domain).'&pruefen=1').((int)($_GET['reward_id']??0)?'&reward_id='.(int)$_GET['reward_id']:'')) ?>"><?= e($initial['action']??'Verfügbarkeit prüfen') ?> <?= icon('arrow') ?></a><button data-domain-retry class="text-button" type="button" hidden>Erneut prüfen</button></div></article>
<p class="small muted">Die Prüfung reserviert deine Domain nicht. Vor der Zahlung prüfen wir die Neuregistrierung erneut. Ein Domainumzug wird individuell angefragt.</p>
<?php if($alternatives): ?><section class="panel domain-alternatives"><div class="panel-title"><div><h2>Weitere passende Endungen</h2><p>Nur Endungen aus unserem Sortiment. Jede Alternative wird einzeln geprüft.</p></div><?= icon('globe') ?></div><div class="domain-alternative-list">
<?php foreach($alternatives as $alternative):$alternativeProduct=domain_priced_product($alternative); ?>
<article class="domain-alternative" data-domain-row data-domain="<?= e($alternative['domain']) ?>"><div class="domain-alternative-name"><h3><?= e($alternative['domain']) ?></h3><span data-domain-status>Noch nicht geprüft</span><p data-domain-message class="small muted">Die Verfügbarkeit wird geprüft.</p></div><div class="domain-result-offer"><strong data-domain-price><?= e(domain_price_label($alternativeProduct)) ?></strong><small data-domain-tax-note>inkl. 19 % MwSt. / Registrierungsjahr</small><a data-domain-action class="button button-outline button-small" href="<?= e(domain_search_url($alternative['domain']).'&pruefen=1'.((int)($_GET['reward_id']??0)?'&reward_id='.(int)$_GET['reward_id']:'')) ?>">Verfügbarkeit prüfen <?= icon('arrow') ?></a><button data-domain-retry class="text-button" type="button" hidden>Erneut prüfen</button></div></article>
<?php endforeach ?></div><?php if(count(domain_suggestions($domain,$offset+8,1))): ?><div class="domain-more"><a class="button button-outline" href="<?= e(domain_search_url($domain).'&mehr='.($offset+8).((int)($_GET['reward_id']??0)?'&reward_id='.(int)$_GET['reward_id']:'')) ?>">Weitere Alternativen anzeigen <?= icon('arrow') ?></a></div><?php endif ?></section><?php elseif(!$offered && domain_catalog_managed()): ?><div class="info-box"><?= icon('globe') ?><span>Derzeit sind keine Domainendungen freigeschaltet.</span></div><?php endif ?>
<div class="button-row"><a class="button button-outline" href="/produkte?kategorie=hosting&amp;domain=<?= e(rawurlencode($domain)) ?>">Passenden Webspace entdecken <?= icon('arrow') ?></a></div>
<?php elseif($offered): ?><section class="panel"><div class="panel-title"><div><h2>Unsere Domainendungen</h2><p>Unsere Preise je Registrierungsjahr, inklusive 19 % MwSt.</p></div></div><div class="domain-price-grid"><?php foreach($offered as $tld): ?><div><strong>.<?= e($tld['extension']) ?></strong><span><?= e(domain_price_label(domain_priced_product($tld))) ?><?= $tld['net_cents']!==null?' / Jahr':'' ?></span></div><?php endforeach ?></div></section><?php endif ?></section>
